Translate the following GNU C++14 code to Java 8 code. The code reads and writes I/O from the console. Your translated code should have the exact same functionality as the given code, meaning that it should have the same output for any given input.
Print your translated code and also the confidence score you give to your translation. The confidence score should be a number between 0 and 1. The format of the output should be:
<translated_code>
<your_translated_code>
</translated_code>
<confidence>
<your_confidence_score>
</confidence>
Do not provide any other text or markdown fences.

Here is the original GNU C++14 code you have to translate:
<original_code>
#include <bits/stdc++.h>
using namespace std;
using ll = long long;

const ll MOD = 1000000007LL;
const int LIM = 1 << 20;

int n, m;
ll cnt[LIM], cnt2[LIM];
ll a[10][10];
int rev[LIM], rev2[LIM];

ll modpow(ll x, ll p) {
    ll r = 1;
    while (p) {
        if (p & 1) r = r * x % MOD;
        x = x * x % MOD;
        p >>= 1;
    }
    return r;
}

bool canMatch(int row, const vector<int>& con, const vector<int>& vi, vector<char>& used) {
    if (row == (int)con.size()) return true;
    for (int idx = 0; idx < (int)vi.size(); ++idx) {
        if (!used[idx] && ((con[row] >> vi[idx]) & 1)) {
            used[idx] = 1;
            if (canMatch(row + 1, con, vi, used)) return true;
            used[idx] = 0;
        }
    }
    return false;
}

void dfs1(int cur, vector<int>& con, ll prob) {
    if (cur == m) {
        int nxt = 0, id = 0;
        for (int j = 0; j < (1 << n); ++j) {
            if (__builtin_popcount(j) != m) continue;
            vector<int> vi;
            for (int i = 0; i < n; ++i) if ((j >> i) & 1) vi.push_back(i);
            vector<char> used(vi.size(), 0);
            int ok = canMatch(0, con, vi, used) ? 1 : 0;
            if (ok) id |= (1 << nxt);
            ++nxt;
        }
        cnt[id] += prob;
        return;
    }
    for (int j = 0; j < (1 << n); ++j) {
        con.push_back(j);
        ll nw = prob;
        for (int k = 0; k < n; ++k) {
            if ((j >> k) & 1) nw = nw * a[cur][k] % MOD;
            else nw = nw * (MOD + 1 - a[cur][k]) % MOD;
        }
        dfs1(cur + 1, con, nw);
        con.pop_back();
    }
}

void dfs2(int cur, vector<int>& con, ll prob) {
    if (cur == n) {
        int nxt = 0, id = 0;
        for (int j = 0; j < (1 << n); ++j) {
            if (__builtin_popcount(j) != n - m) continue;
            vector<int> vi;
            for (int i = 0; i < n; ++i) if ((j >> i) & 1) vi.push_back(i);
            vector<char> used(vi.size(), 0);
            int ok = canMatch(0, con, vi, used) ? 1 : 0;
            if (ok) id |= (1 << nxt);
            ++nxt;
        }
        cnt2[id] += prob;
        return;
    }
    for (int j = 0; j < (1 << n); ++j) {
        con.push_back(j);
        ll nw = prob;
        for (int k = 0; k < n; ++k) {
            if ((j >> k) & 1) nw = nw * a[cur][k] % MOD;
            else nw = nw * (MOD + 1 - a[cur][k]) % MOD;
        }
        dfs2(cur + 1, con, nw);
        con.pop_back();
    }
}

int main() {
    cin >> n;
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            cin >> a[i][j];
            a[i][j] = a[i][j] * modpow(100LL, MOD - 2) % MOD;
            a[i][j] = (a[i][j] % MOD + MOD) % MOD;
        }
    }
    if (n == 1) {
        cout << a[0][0] << '\n';
        return 0;
    }
    m = n / 2;

    vector<int> con;
    dfs1(0, con, 1);
    for (int i = 0; i < LIM; ++i) cnt[i] %= MOD;
    for (int i = 0; i < 20; ++i) {
        for (int j = 0; j < LIM; ++j) {
            if ((j >> i) & 1) {
                cnt[j] += cnt[j ^ (1 << i)];
                cnt[j] %= MOD;
            }
        }
    }
    ll all = cnt[LIM - 1];

    con.clear();
    dfs2(m, con, 1);
    for (int i = 0; i < LIM; ++i) cnt2[i] %= MOD;

    memset(rev, -1, sizeof(rev));
    int nd = 0;
    for (int i = 0; i < (1 << n); ++i) {
        if (__builtin_popcount(i) == m) rev[i] = nd++;
    }

    memset(rev2, -1, sizeof(rev2));
    nd = 0;
    int cor[25] = {};
    for (int i = 0; i < (1 << n); ++i) {
        if (__builtin_popcount(i) == n - m) {
            cor[nd] = rev[(1 << n) - 1 - i];
            rev2[i] = nd++;
        }
    }

    ll ans = 0;
    for (int i = 0; i < (1 << nd); ++i) {
        ll cur = cnt2[i];
        int mask = 0;
        for (int j = 0; j < nd; ++j) {
            if (((i >> j) & 1));
            else mask += (1 << cor[j]);
        }
        ans += cur * (all - cnt[mask]) % MOD;
    }
    cout << (ans % MOD + MOD) % MOD << '\n';
    return 0;
}
